namespace pugi
{
	// Character type used for all internal storage and operations; depends on PUGIXML_WCHAR_MODE
	typedef PUGIXML_CHAR char_t;
}

namespace pugi
{
#ifndef PUGIXML_NO_STL
	// String type used for operations that work with STL string; depends on PUGIXML_WCHAR_MODE
	typedef std::basic_string<PUGIXML_CHAR> string_t;
#endif
}

namespace pugi
{
#ifdef PUGIXML_HAS_STRING_VIEW
	// String view type used for operations that can work with a length delimited string; depends on PUGIXML_WCHAR_MODE
	typedef std::basic_string_view<PUGIXML_CHAR> string_view_t;
#endif
}

namespace pugi
{
	// Tree node types
	enum xml_node_type
	{
		node_null,
		node_document,
		node_element,
		node_pcdata,
		node_cdata,
		node_comment,
		node_pi,
		node_declaration,
		node_doctype
	};
}

namespace pugi
{
	// These flags determine the encoding of input data for XML document
	enum xml_encoding
	{
		encoding_auto,
		encoding_utf8,
		encoding_utf16_le,
		encoding_utf16_be,
		encoding_utf16,
		encoding_utf32_le,
		encoding_utf32_be,
		encoding_utf32,
		encoding_wchar,
		encoding_latin1
	};
}

namespace pugi
{
	// Forward declarations
	struct xml_attribute_struct;
}

namespace pugi
{
	// Forward declarations
	struct xml_node_struct;
}

class PUGIXML_CLASS xml_writer
	{
	public:
		virtual ~xml_writer();

		// Write memory chunk into stream/file/whatever
		virtual void write(const void* data, size_t size) = 0;
	};

class PUGIXML_CLASS xml_writer_file: public xml_writer
	{
	public:
		// Construct writer from a FILE* object; void* is used to avoid header dependencies on stdio
		xml_writer_file(void* file);

		virtual void write(const void* data, size_t size) PUGIXML_OVERRIDE;

	private:
		void* file;
	};

#ifndef PUGIXML_NO_STL
class PUGIXML_CLASS xml_writer_stream: public xml_writer
	{
	public:
		// Construct writer from an output stream object
		xml_writer_stream(std::basic_ostream<char>& stream);
		xml_writer_stream(std::basic_ostream<wchar_t>& stream);

		virtual void write(const void* data, size_t size) PUGIXML_OVERRIDE;

	private:
		std::basic_ostream<char>* narrow_stream;
		std::basic_ostream<wchar_t>* wide_stream;
	};
#endif

class PUGIXML_CLASS xml_attribute
	{
		friend class xml_attribute_iterator;
		friend class xml_node;

	private:
		xml_attribute_struct* _attr;

		typedef void (*unspecified_bool_type)(xml_attribute***);

	public:
		xml_attribute();
		explicit xml_attribute(xml_attribute_struct* attr);
		operator unspecified_bool_type() const;
		bool operator!() const;
		bool operator==(const xml_attribute& r) const;
		bool operator!=(const xml_attribute& r) const;
		bool operator<(const xml_attribute& r) const;
		bool operator>(const xml_attribute& r) const;
		bool operator<=(const xml_attribute& r) const;
		bool operator>=(const xml_attribute& r) const;
		bool empty() const;
		const char_t* name() const;
		const char_t* value() const;
		const char_t* as_string(const char_t* def = PUGIXML_TEXT("")) const;
		int as_int(int def = 0) const;
		unsigned int as_uint(unsigned int def = 0) const;
		double as_double(double def = 0) const;
		float as_float(float def = 0) const;
	#ifdef PUGIXML_HAS_LONG_LONG
		long long as_llong(long long def = 0) const;
		unsigned long long as_ullong(unsigned long long def = 0) const;
	#endif
		bool as_bool(bool def = false) const;
		bool set_name(const char_t* rhs);
		bool set_name(const char_t* rhs, size_t size);
	#ifdef PUGIXML_HAS_STRING_VIEW
		bool set_name(string_view_t rhs);
	#endif
		bool set_value(const char_t* rhs);
		bool set_value(const char_t* rhs, size_t size);
	#ifdef PUGIXML_HAS_STRING_VIEW
		bool set_value(string_view_t rhs);
	#endif
		bool set_value(int rhs);
		bool set_value(unsigned int rhs);
		bool set_value(long rhs);
		bool set_value(unsigned long rhs);
		bool set_value(double rhs);
		bool set_value(double rhs, int precision);
		bool set_value(float rhs);
		bool set_value(float rhs, int precision);
		bool set_value(bool rhs);
	#ifdef PUGIXML_HAS_LONG_LONG
		bool set_value(long long rhs);
		bool set_value(unsigned long long rhs);
	#endif
		xml_attribute& operator=(const char_t* rhs);
		xml_attribute& operator=(int rhs);
		xml_attribute& operator=(unsigned int rhs);
		xml_attribute& operator=(long rhs);
		xml_attribute& operator=(unsigned long rhs);
		xml_attribute& operator=(double rhs);
		xml_attribute& operator=(float rhs);
		xml_attribute& operator=(bool rhs);
	#ifdef PUGIXML_HAS_STRING_VIEW
		xml_attribute& operator=(string_view_t rhs);
	#endif
	#ifdef PUGIXML_HAS_LONG_LONG
		xml_attribute& operator=(long long rhs);
		xml_attribute& operator=(unsigned long long rhs);
	#endif
		xml_attribute next_attribute() const;
		xml_attribute previous_attribute() const;
		size_t hash_value() const;
		xml_attribute_struct* internal_object() const;
	};

