import random
import os
import struct
from typing import List

# Target data type: arbitrary binary data for xml_writer::write sinks.
# The writers accept any bytes; we generate valid non-empty buffers (<=1024 bytes).

_MAX = 1024

_def_boundary_sizes = [
    1,2,3,4,5,7,8,15,16,31,32,63,64,95,96,127,128,191,192,255,256,511,512,768,1023,1024
]

_ascii_samples = [
    b"\n", b"\r\n", b" ", b"\t", b"A", b"a", b"0", b"<", b">", b"/", b"\\", b"'", b'"'
]

_xml_like_snippets = [
    b"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n",
    b"<!-- comment -->\n",
    b"<root>",
    b"<elem attr=\"value\">text</elem>",
    b"<![CDATA[some cdata \x00 binary]]>",
    b"</root>\n",
]

_fill_bytes = [0x00, 0xFF, 0x20, 0x09, 0x0A, 0x41, 0x61]


def _rand_len(rng: random.Random) -> int:
    if rng.random() < 0.6:
        return rng.choice(_def_boundary_sizes)
    return rng.randint(1, _MAX)


def _pattern_fill(length: int, byte_val: int) -> bytes:
    return bytes([byte_val]) * length


def _inc_sequence(length: int, start: int = 0, step: int = 1) -> bytes:
    return bytes(((start + i * step) & 0xFF for i in range(length)))


def _rand_runs(rng: random.Random, length: int) -> bytes:
    out = bytearray()
    while len(out) < length:
        b = rng.randrange(256)
        run = min(length - len(out), int(rng.expovariate(1/16)) + 1)
        out.extend([b] * run)
    if len(out) > length:
        del out[length:]
    return bytes(out)


def _xml_like(rng: random.Random, length: int) -> bytes:
    chunks: List[bytes] = []
    while sum(len(c) for c in chunks) < min(length, 200):
        chunks.append(rng.choice(_xml_like_snippets))
        if rng.random() < 0.3:
            chunks.append(b" attr=\"" + bytes([rng.randrange(97, 123)]) + b"\"")
        if rng.random() < 0.2:
            chunks.append(rng.choice(_ascii_samples))
    data = b"".join(chunks)
    if len(data) >= length:
        return data[:length]
    pad_len = length - len(data)
    pad = bytearray()
    while len(pad) < pad_len:
        choice = rng.random()
        if choice < 0.4:
            pad.append(rng.randrange(32, 127))
        elif choice < 0.8:
            pad.extend(b" ")
        else:
            pad.append(0)
    if len(pad) > pad_len:
        pad = pad[:pad_len]
    return data + bytes(pad)


def _pack_u32_or_i32(rng: random.Random) -> bytes:
    # Choose a 32-bit packing format safely respecting value ranges
    fmt = rng.choice(["<I", ">I", "<i", ">i"])  # unsigned or signed
    if fmt.endswith("I"):
        val = rng.getrandbits(32)
    else:
        # signed 32-bit range
        val = rng.randrange(-2147483648, 2147483647)
    return struct.pack(fmt, val)


def _mixed(rng: random.Random, length: int) -> bytes:
    out = bytearray()
    while len(out) < length:
        remaining = length - len(out)
        mode = rng.randrange(6)
        chunk_len = min(remaining, rng.choice([1,2,3,4,8,16,32,64,128,256,remaining]))
        if mode == 0:
            out.extend(_pattern_fill(chunk_len, rng.choice(_fill_bytes)))
        elif mode == 1:
            out.extend(_inc_sequence(chunk_len, rng.randrange(256), rng.choice([1, -1, 2, -2, 7, 13, 31])))
        elif mode == 2:
            out.extend(_rand_runs(rng, chunk_len))
        elif mode == 3:
            out.extend(os.urandom(min(chunk_len, 64)))
            if len(out) < length:
                more = min(length - len(out), max(0, chunk_len - 64))
                out.extend(rng.getrandbits(8) for _ in range(more))
        elif mode == 4:
            pkt = _pack_u32_or_i32(rng)
            out.extend(pkt)
            fill = min(chunk_len - len(pkt), remaining - len(pkt))
            if fill > 0:
                out.extend(_pattern_fill(fill, rng.choice(_fill_bytes)))
        else:
            out.extend(_xml_like(rng, chunk_len))
    if len(out) > length:
        del out[length:]
    return bytes(out)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    length = _rand_len(rng)

    strategies = [
        lambda: _pattern_fill(length, rng.choice(_fill_bytes)),
        lambda: _inc_sequence(length, rng.randrange(256), rng.choice([1, -1, 2, -2, 7, 13, 31])),
        lambda: _rand_runs(rng, length),
        lambda: _xml_like(rng, length),
        lambda: _mixed(rng, length),
        lambda: os.urandom(length),
    ]

    weights = [0.1, 0.15, 0.2, 0.15, 0.3, 0.1]
    pick = rng.random()
    acc = 0.0
    chosen = strategies[-1]
    for strat, w in zip(strategies, weights):
        acc += w
        if pick <= acc:
            chosen = strat
            break

    data = chosen()

    if not data:
        data = b"\x00"
    if len(data) > _MAX:
        data = data[:_MAX]
    return data

import random
import string
from typing import List, Tuple

# We generate valid and interesting XML buffers covering:
# - XML declarations with various encodings
# - Doctype, comments, CDATA, PIs
# - Mixed content, attributes, namespaces, entity refs
# - Different newline styles
# - Varying whitespace/indentation
# - Optional BOMs for UTF-8/16/32 with matching encoding declarations
# Keep size <= 4096 bytes.

XML_ENTITIES = [
    "&lt;", "&gt;", "&amp;", "&quot;", "&apos;",
    "&#10;", "&#x0A;", "&#x20;", "&#x7F;", "&#xA9;",
]

NS_PREFIXES = ["ns", "x", "p", "a", "b", "cfg", "u"]

TAGS = [
    "root", "r", "node", "item", "entry", "data", "c", "n", "α", "名前"
]

ATTR_NAMES = [
    "id", "name", "value", "class", "enabled", "count", "ref", "lang", "xml:lang"
]

PI_TARGETS = ["xml-stylesheet", "processing", "pi", "x" ]

DOCTYPES = [
    ("root", "<!DOCTYPE root PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd\">"),
    ("root", "<!DOCTYPE root [ <!ELEMENT root ANY> <!ATTLIST root id ID #IMPLIED> ]>")
]

NEWLINES = ["\n", "\r\n", "\r"]


def _rand_choice(rng: random.Random, seq: List):
    return seq[rng.randrange(len(seq))]


def _rand_ident(rng: random.Random, base_list: List[str], max_extra: int = 3) -> str:
    base = _rand_choice(rng, base_list)
    extra = ''.join(rng.choice(string.ascii_letters + string.digits) for _ in range(rng.randrange(max_extra+1)))
    if extra:
        return f"{base}{extra}"
    return base


def _rand_attr_value(rng: random.Random) -> str:
    parts = []
    for _ in range(rng.randrange(1, 4)):
        kind = rng.randrange(5)
        if kind == 0:
            parts.append(''.join(rng.choice(string.ascii_letters) for _ in range(rng.randrange(1,6))))
        elif kind == 1:
            parts.append(str(rng.randrange(0, 100000)))
        elif kind == 2:
            parts.append(_rand_choice(rng, XML_ENTITIES))
        elif kind == 3:
            parts.append('-'.join(_rand_ident(rng, TAGS).split()))
        else:
            parts.append(''.join(rng.choice(' _:/.-') for _ in range(rng.randrange(1,4))))
    val = ''.join(parts)
    # randomly choose quotes
    if '"' in val and "'" not in val:
        return f"'{val}'"
    elif "'" in val and '"' not in val:
        return f'"{val}"'
    else:
        # escape quotes if needed by picking the other quote randomly
        if rng.random() < 0.5:
            return '"' + val.replace('"', '&quot;') + '"'
        else:
            return "'" + val.replace("'", "&apos;") + "'"


def _gen_attrs(rng: random.Random, with_ns: bool) -> str:
    k = rng.randrange(0, 5)
    attrs = []
    for _ in range(k):
        if with_ns and rng.random() < 0.3:
            # namespace decl
            if rng.random() < 0.5:
                prefix = _rand_choice(rng, NS_PREFIXES)
                attrs.append(f"xmlns:{prefix}='urn:{prefix}:{rng.randrange(100)}'")
            else:
                attrs.append(f"xmlns='urn:default:{rng.randrange(100)}'")
        else:
            name = _rand_choice(rng, ATTR_NAMES)
            # optionally prefix
            if with_ns and rng.random() < 0.4:
                name = f"{_rand_choice(rng, NS_PREFIXES)}:{name}"
            attrs.append(f"{name}={_rand_attr_value(rng)}")
    return (' ' + ' '.join(attrs)) if attrs else ''


def _gen_text(rng: random.Random) -> str:
    parts = []
    for _ in range(rng.randrange(1, 5)):
        kind = rng.randrange(6)
        if kind in (0, 1):
            parts.append(''.join(rng.choice(string.ascii_letters + string.digits + ' ') for _ in range(rng.randrange(3, 10))))
        elif kind == 2:
            parts.append(_rand_choice(rng, XML_ENTITIES))
        elif kind == 3:
            parts.append(f"<![CDATA[{''.join(rng.choice(string.printable) for _ in range(rng.randrange(1, 8)))}]]>")
        elif kind == 4:
            parts.append(f"<!-- {''.join(rng.choice(string.ascii_letters+' ') for _ in range(rng.randrange(1,8)))} -->")
        else:
            parts.append('')
    return ''.join(parts)


def _gen_children(rng: random.Random, depth: int, max_depth: int, indent: str, newline: str) -> str:
    if depth >= max_depth:
        return _gen_text(rng)
    n_children = rng.randrange(1, 5)
    out = []
    for i in range(n_children):
        tag = _rand_ident(rng, TAGS)
        ns = rng.random() < 0.5
        attrs = _gen_attrs(rng, with_ns=ns)
        if rng.random() < 0.2:
            # empty element
            out.append(f"{indent*depth}<{tag}{attrs}/>{newline}")
        else:
            content = ''
            if rng.random() < 0.6:
                content += _gen_text(rng)
            if rng.random() < 0.7:
                content += _gen_children(rng, depth+1, max_depth, indent, newline)
            out.append(f"{indent*depth}<{tag}{attrs}>{content}</{tag}>{newline}")
        if rng.random() < 0.2:
            # add a PI or comment between siblings
            if rng.random() < 0.5:
                target = _rand_choice(rng, PI_TARGETS)
                out.append(f"{indent*depth}<?{target} type='text/xsl' href='style.xsl'?>{newline}")
            else:
                out.append(f"{indent*depth}<!-- sibling-sep -->{newline}")
    return ''.join(out)


def _maybe_decl(rng: random.Random) -> Tuple[str, str, bytes]:
    # Returns (decl, encoding_name, optional_bom)
    if rng.random() < 0.85:
        enc_choice = rng.randrange(5)  # utf-8/16/32 and none
        if enc_choice == 0:
            return ("<?xml version=\"1.0\" encoding=\"UTF-8\"?>", "utf-8", b"\xEF\xBB\xBF" if rng.random() < 0.3 else b"")
        elif enc_choice == 1:
            # We will still emit UTF-8 text; parser may ignore conflict based on caller-provided encoding.
            return ("<?xml version=\"1.0\" encoding=\"UTF-16\"?>", "utf-16", b"")
        elif enc_choice == 2:
            return ("<?xml version=\"1.0\" encoding=\"UTF-32\"?>", "utf-32", b"")
        elif enc_choice == 3:
            return ("<?xml version=\"1.0\"?>", "", b"")
        else:
            return ("<?xml version=\"1.0\" encoding=\"ISO-8859-1\"?>", "latin1", b"")
    return ("", "", b"")


def _maybe_doctype(rng: random.Random, root_name: str, newline: str) -> str:
    if rng.random() < 0.5:
        name, dt = _rand_choice(rng, DOCTYPES)
        # align root name sometimes
        if rng.random() < 0.5:
            dt = dt.replace("root", root_name)
        return dt + newline
    return ""


def _build_document(rng: random.Random) -> str:
    newline = _rand_choice(rng, NEWLINES)
    indent = '    ' if rng.random() < 0.6 else '\t'
    decl, enc, _ = _maybe_decl(rng)
    root = _rand_ident(rng, TAGS)
    preamble = []
    if decl:
        preamble.append(decl + newline)
    # Optional top-level comment or PI
    if rng.random() < 0.6:
        preamble.append(f"<!-- generated -->{newline}")
    if rng.random() < 0.5:
        preamble.append(f"<?{_rand_choice(rng, PI_TARGETS)} mode='on'?>{newline}")
    preamble.append(_maybe_doctype(rng, root, newline))

    # Optional namespace on root
    root_attrs = _gen_attrs(rng, with_ns=True)

    children = _gen_children(rng, depth=1, max_depth=rng.randrange(2, 5), indent=indent, newline=newline)
    text_before = _gen_text(rng) if rng.random() < 0.3 else ''
    text_after = _gen_text(rng) if rng.random() < 0.3 else ''

    doc = ''.join(preamble)
    doc += f"<{root}{root_attrs}>{newline}{text_before}{children}{text_after}</{root}>{newline}"
    return doc


def _wrap_as_fragment(rng: random.Random) -> str:
    # For append_buffer target, provide an XML fragment that can be appended under an element:
    # mixture of elements, comments, text, CDATA, PI. No XML decl/doctype at fragment level.
    newline = _rand_choice(rng, NEWLINES)
    indent = '  '
    parts = []
    if rng.random() < 0.5:
        parts.append(f"<!-- fragment start -->{newline}")
    parts.append(_gen_children(rng, depth=0, max_depth=rng.randrange(1, 3), indent=indent, newline=newline))
    if rng.random() < 0.4:
        parts.append(f"<?note info='appended'?>{newline}")
    if rng.random() < 0.4:
        parts.append(_gen_text(rng))
    return ''.join(parts)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose between full document (for load_buffer/load_file) and fragment (for append_buffer)
    mode = rng.random()
    if mode < 0.45:
        # Full document
        xml_text = _build_document(rng)
        decl, enc_name, bom = _maybe_decl(rng)
        # Prepend BOM with some probability; avoid double decl by using the decl from _build_document already
        if bom and not xml_text.startswith("\ufeff"):
            data = bom + xml_text.encode('utf-8', errors='strict')
        else:
            data = xml_text.encode('utf-8', errors='strict')
    elif mode < 0.9:
        # Fragment
        frag = _wrap_as_fragment(rng)
        data = frag.encode('utf-8', errors='strict')
    else:
        # Minimal well-formed small doc to ensure at least one parser-success path
        data = b"<r><c id='1'/>text<![CDATA[xyz]]><!--k--></r>"

    # Ensure size bound
    if len(data) > 4096:
        data = data[:4096]
    # Guarantee non-empty as required by fuzz stubs
    if not data:
        data = b"<r/>"
    return data
